const raw = ($json.published_at || '').toString().trim();
let iso = null;

if (raw) {
  let dt = DateTime.fromISO(raw);                       // 2026-11-07T14:30:00Z
  if (!dt.isValid) dt = DateTime.fromRFC2822(raw);      // Sat, 07 Nov 2026 14:30:00 GMT (RSS style)
  if (!dt.isValid) {                                    // 2026年11月7日, 2026/11/07, 2026.11.07
    const m = raw.match(/(\d{4})[年\/.-](\d{1,2})[月\/.-](\d{1,2})/);
    if (m) dt = DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] });
  }
  if (!dt.isValid) {                                    // last resort: JavaScript's own parser
    const d = new Date(raw);
    if (!isNaN(d)) dt = DateTime.fromJSDate(d);
  }
  iso = dt.isValid ? dt.toISO() : null;
}

return { json: { ...$json, published_at: iso } };

const VALID = new Set($('Load Opportunities').item.json.valid_ids);

const doc = $('Insert document').item.json;   // source_id, url, hash, text
const out = $json.output || {};
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const docText = norm(doc.text);

const rawClaims = Array.isArray(out.claims) ? out.claims : [];
const claims = rawClaims.filter(c =>
  VALID.has(c.opportunity_id) &&            // real opportunity ID
  norm(c.support_quote).length > 0 &&
  docText.includes(norm(c.support_quote))   // quote really appears in the article
);

const score = n => {
  n = Math.round(Number(n));
  return Number.isFinite(n) ? Math.min(5, Math.max(1, n)) : null;
};

return { json: {
  source_id: doc.source_id,
  url: doc.url,
  hash: doc.hash,
  credibility_score: score(out.credibility_label),
  relevance_score: score(out.relevance_score),
  relevance_justification_en: out.relevance_justification_en || '',
  summary_en: out.summary_en || '',
  claims_json: JSON.stringify(claims),
  claims_dropped: rawClaims.length - claims.length,
  analyzed_at: $now.toISO()
}};

const doc = $('Insert document').item.json;
const opps = $json.data;
const text = opps.map(o =>
  `${o.opportunity_id} | ${o.title} | stage: ${o.stage} | counts only if the article reports: ${o.monitor_triggers.join('; ')}`
).join('\n');
return { json: { ...doc, opportunities: text, valid_ids: opps.map(o => o.opportunity_id) } };

const out = [];
for (const item of $('Verify AI Claims').all()) {
  const d = item.json;
  let claims = [];
  try { claims = JSON.parse(d.claims_json || '[]'); } catch (e) {}
  for (const c of claims) {
    // the model sometimes returns "January 2026" or "unknown"; keep only YYYY-MM-DD
    const date = /^\d{4}-\d{2}-\d{2}$/.test(c.event_date || '') ? c.event_date : null;
    out.push({ json: {
      opportunity_id: c.opportunity_id,
      dimension: c.dimension,
      value: c.value,
      event_date: date,
      claim_en: c.claim_en,
      locator: c.locator,
      support_quote: c.support_quote,
      source_id: d.source_id,
      hash: d.hash,
      run_id: Number($execution.id)
    }});
  }
}
return out;

const events = $('Insert Event').all().map(i => i.json);
const state = {};   // key = opportunity|dimension -> current row
for (const i of $input.all()) {
  const r = i.json;
  if (r.opportunity_id) state[`${r.opportunity_id}|${r.dimension}`] = { ...r, _action: null, _prev_value: r.value, _prev_date: r.event_date };
}
const day = d => (d ? String(d).slice(0, 10) : null);

for (const ev of events) {
  const key = `${ev.opportunity_id}|${ev.dimension}`;
  const cur = state[key];
  const d = day(ev.event_date);
  if (!cur) {
    // no row yet: insert
    state[key] = { opportunity_id: ev.opportunity_id, dimension: ev.dimension, value: ev.value,
      event_date: ev.event_date, event_id: String(ev.id), conflict: false, conflict_value: null, _action: 'insert' };
  } else if (d && (!day(cur.event_date) || d > day(cur.event_date))) {
    // newer event: replace and clear any conflict
    Object.assign(cur, { value: ev.value, event_date: ev.event_date, event_id: String(ev.id), conflict: false, conflict_value: null });
    cur._action = cur._action || 'update';   // stays 'insert' if it was added earlier in this run
  } else if (d && d === day(cur.event_date) && ev.value !== cur.value) {
    // same date, different value: flag a conflict
    Object.assign(cur, { conflict: true, conflict_value: ev.value });
    cur._action = cur._action || 'update';
  }
  // older date, same value, or no date on an existing row: ignored
}
return Object.values(state).filter(r => r._action).map(r => ({ json: r }));

const events = Object.fromEntries($('Insert Event').all().map(i => [String(i.json.id), i.json]));
const changes = $input.all().map(i => i.json).filter(c => c.opportunity_id);
const day = d => (d ? String(d).slice(0, 10) : 'date unknown');

const item = c => {
  const ev = events[c.event_id] || {};
  const prev = c._action === 'insert' ? 'none (first record)' : `${c._prev_value} (${day(c._prev_date)})`;
  return [
    `- **${c.opportunity_id}** | ${c.dimension}: ${c.value}`,
    `  - **Previous:** ${prev}`,
    `  - **Evidence (${day(c.event_date)}):** ${ev.claim_en || 'n/a'} [${ev.source_id || '?'}; ${ev.locator || 'no locator'}]`,
    `  - **Quote:** "${ev.support_quote || ''}"`,
    c.conflict ? `  - **CONFLICT:** another source reports "${c.conflict_value}" on the same date.` : null,
    `  - **Review:** verify against the primary source before treating this as current.`,
  ].filter(Boolean).join('\n');
};

const section = (title, items) => items.length ? `## ${title} (${items.length})\n\n${items.map(item).join('\n\n')}` : null;

const conflicts = changes.filter(c => c.conflict);
const rest = changes.filter(c => !c.conflict);
const newLeads = rest.filter(c => c._action === 'insert');
const updates = rest.filter(c => c._action === 'update');

const parts = [
  `# Daily change note`,
  `**As of ${$now.toISODate()}.** VALIDATION DRAFT: claims are AI-extracted and unreviewed. Not for distribution.`,
  `**Summary:** ${newLeads.length} new, ${updates.length} updated, ${conflicts.length} conflicts.`,
  section('Conflicts needing review', conflicts),
  section('New leads', newLeads),
  section('Material updates', updates),
  changes.length ? null : `_No state changes this run. This is not "no change" if any source failed._`,
].filter(Boolean);

return [{ json: { filename: `change_note_${$now.toFormat('yyyy-MM-dd_HHmm')}.md`, markdown: parts.join('\n\n') + '\n' } }];
